CREATE TABLE "chat_snippets" (
  "key" varchar(40) PRIMARY KEY NOT NULL,
  "title" varchar(120) NOT NULL,
  "body" text NOT NULL,
  "quick_replies" jsonb DEFAULT '[]'::jsonb NOT NULL,
  "trigger_label" varchar(80),
  "sort_order" integer DEFAULT 0 NOT NULL,
  "updated_at" timestamp with time zone DEFAULT now() NOT NULL
);--> statement-breakpoint
INSERT INTO "chat_snippets" ("key", "title", "body", "quick_replies", "trigger_label", "sort_order") VALUES
('welcome', 'Boas-vindas', E'Oi! Eu sou o Elio, seu assistente financeiro 💜 Estou aqui para te dar clareza sobre o seu dinheiro, sem planilha e sem burocracia.\n\nJá deixei as suas categorias prontas. Para começar, só uma pergunta: **o que você mais quer da sua vida financeira agora?** Toque numa opção ou me conte do seu jeito, digitando ou falando.', '["Organizar meu mês", "Juntar uma reserva", "Quitar dívidas", "Realizar um sonho", "Entender para onde vai meu dinheiro", "Como o Realwise funciona?"]', NULL, 0),
('intro', 'Como o Realwise funciona', E'O Realwise é o seu assistente financeiro de bolso, e eu sou o Elio. 💜\n\nÉ simples:\n- **Você conversa comigo.** Digite ou fale: "gastei 45 no mercado" e eu anoto.\n- **Eu organizo para você.** Mando o extrato ou a fatura e eu categorizo tudo, sem digitar nada.\n- **Eu aviso das contas.** Você recebe um lembrete antes de cada vencimento, para nunca mais pagar multa.\n- **Todo mês, o seu resumo.** Uma nota de saúde financeira com para onde foi o seu dinheiro e o que ajustar.\n\nSeus dados são só seus, e dá para apagar tudo quando quiser.', '["Quero definir meu objetivo", "Como importo meu extrato?"]', 'Como o Realwise funciona?', 1),
('import', 'Como importar o extrato', E'Importar é rápido, e dá para fazer quando você quiser:\n\n- Toque no clipe 📎 aqui no chat e anexe o **PDF, foto, CSV, XLSX ou OFX** do extrato ou da fatura (vários de uma vez, se preferir).\n- Eu leio, separo as entradas das saídas e categorizo tudo.\n- O que eu não tiver certeza, eu pergunto antes de fechar.\n\nSem pressa: você também pode só me contar os gastos do dia, digitando ou falando.', '["Como o Realwise funciona?"]', 'Como importo meu extrato?', 2),
('bills', 'Lembretes de contas', E'Você pode me contar uma conta assim: "aluguel dia 5, R$ 1.800". Eu crio o lembrete e te aviso por e-mail antes de vencer. Quando pagar, é só me dizer "paguei o aluguel" que eu dou baixa.', '["Como o Realwise funciona?"]', 'Como funcionam os lembretes de contas?', 3),
('planner', 'Planejamento do mês', E'Com a sua renda eu monto um plano simples entre **necessidades, desejos e poupança** (a base é 50/30/20, ajustada aos seus objetivos). Você acompanha o quanto já usou de cada parte durante o mês, e pode mudar o plano quando quiser, aqui ou na tela de Planejamento.', '["Como o Realwise funciona?"]', 'Como funciona o planejamento?', 4),
('summary', 'Resumo do mês', E'Todo começo de mês você recebe um resumo: sua **nota de saúde financeira**, para onde foi cada real, como foi comparado aos meses anteriores e o que ajustar. Chega por e-mail e abre numa página privada só sua. Quer ver agora? É só pedir "meu resumo".', '["Como o Realwise funciona?"]', 'O que é o resumo do mês?', 5),
('privacy', 'Seus dados', E'Seus dados são seus: nada é vendido e você pode apagar tudo quando quiser em Configurações. Em "O que o Elio sabe sobre você" você vê e apaga tudo o que eu guardei.', '["Como o Realwise funciona?"]', 'Meus dados estão seguros?', 6);
